let __isAdmin=false;
let __adminSessionEmail='';
(function(){
  const dbg=new URLSearchParams(location.search).get('debug')==='1';
  try{
    const cfg=window.RGPD_CONFIG;
    if(!cfg){if(dbg)alert('DEBUG: RGPD_CONFIG absent');return}
    if(!window.supabase){if(dbg)alert('DEBUG: librairie supabase-js non chargée (window.supabase absent)');return}
    const supaUrl=cfg.apiUrl.split('/functions/')[0];
    const sb=window.supabase.createClient(supaUrl,cfg.publishableKey);
    window.__sbAuth=sb;
    const sync=()=>sb.auth.getSession().then(({data,error})=>{
      const session=data&&data.session;
      const current=String(session?.user?.email||'').trim().toLowerCase();
      const expected=String(cfg.adminEmail||'').trim().toLowerCase();
      __adminSessionEmail=current;
      __isAdmin=!!session&&!!expected&&current===expected;
      document.dispatchEvent(new CustomEvent('rgpd-admin-auth-change',{detail:{isAdmin:__isAdmin,email:current}}));
      if(dbg)alert('DEBUG admin='+__isAdmin+(session?' email='+session.user.email:' (pas de session)')+(error?' err='+error.message:''));
    }).catch(e=>{
      __isAdmin=false;
      __adminSessionEmail='';
      document.dispatchEvent(new CustomEvent('rgpd-admin-auth-change',{detail:{isAdmin:false,email:''}}));
      if(dbg)alert('DEBUG catch: '+e.message);
    });
    sync();
    sb.auth.onAuthStateChange(()=>sync());
  }catch(e){if(dbg)alert('DEBUG exception: '+e.message)}
})();
function auditAccess(){return __isAdmin===true}
const A=["Gouvernance","Registre","Principes","Transparence & droits","Consentement","Sous-traitance","Sécurité","Violations","AIPD & privacy by design","Transferts hors EEE"];const Qs=[{"id":"g1","axis":"Gouvernance","text":"Une personne pilote-t-elle formellement la conformité RGPD ?","ref":"Art. 5.2, 24","proof":"Lettre de mission, RACI, reporting","action":"Désigner un pilote et formaliser ses responsabilités.","level":1,"critical":true},{"id":"g2","axis":"Gouvernance","text":"Le DPO est-il désigné lorsque sa nomination est obligatoire ?","ref":"Art. 37 à 39","proof":"Analyse d'obligation, notification CNIL","action":"Évaluer l'obligation et désigner le DPO si nécessaire.","level":2,"critical":true},{"id":"g4","axis":"Gouvernance","text":"Les collaborateurs sont-ils régulièrement sensibilisés ?","ref":"Art. 39.1.b","proof":"Plan, supports et preuves de formation","action":"Déployer une sensibilisation initiale puis périodique.","level":2,"critical":false},{"id":"r1","axis":"Registre","text":"Un registre des traitements existe-t-il et reflète-t-il la réalité ?","ref":"Art. 30","proof":"Registre daté et historique","action":"Créer ou actualiser le registre des traitements.","level":1,"critical":true},{"id":"r2","axis":"Registre","text":"Chaque fiche précise-t-elle finalités, données, personnes, destinataires et durées ?","ref":"Art. 30","proof":"Fiches complètes et validées","action":"Compléter les champs obligatoires.","level":2,"critical":false},{"id":"p1","axis":"Principes","text":"Une base légale valide est-elle définie pour chaque finalité ?","ref":"Art. 5.1.a, 6, 9","proof":"Registre et analyse juridique","action":"Documenter une base légale par finalité.","level":1,"critical":true},{"id":"p2","axis":"Principes","text":"Les données collectées sont-elles strictement nécessaires ?","ref":"Art. 5.1.c","proof":"Revue des formulaires et champs","action":"Supprimer les collectes non nécessaires.","level":2,"critical":false},{"id":"p3","axis":"Principes","text":"Des durées de conservation précises sont-elles définies et appliquées ?","ref":"Art. 5.1.e","proof":"Politique, archivage, journaux de purge","action":"Définir puis appliquer archivage et suppression.","level":1,"critical":true},{"id":"p4","axis":"Principes","text":"Les finalités sont-elles définies avant collecte et les réutilisations contrôlées ?","ref":"Art. 5.1.b, 6.4","proof":"Fiches projet, tests de compatibilité","action":"Valider formellement toute nouvelle finalité.","level":2,"critical":false},{"id":"t1","axis":"Transparence & droits","text":"Les personnes reçoivent-elles une information claire au moment approprié ?","ref":"Art. 12 à 14","proof":"Mentions, formulaires, écrans","action":"Mettre à jour et déployer les mentions.","level":1,"critical":true},{"id":"t2","axis":"Transparence & droits","text":"Les mentions couvrent-elles toutes les informations obligatoires ?","ref":"Art. 13, 14","proof":"Grille de contrôle des mentions","action":"Vérifier bases, durées, droits et destinataires.","level":2,"critical":false},{"id":"t3","axis":"Transparence & droits","text":"Les droits peuvent-ils être traités dans le délai d’un mois ?","ref":"Art. 12.3, 15 à 22","proof":"Procédure, registre, modèles","action":"Formaliser réception, instruction et réponse.","level":1,"critical":true},{"id":"c1","axis":"Consentement","text":"Quand il est utilisé, le consentement est-il libre, spécifique, éclairé et univoque ?","ref":"Art. 4.11, 7","proof":"Formulaires, parcours et paramétrage","action":"Corriger les mécanismes de consentement.","level":1,"critical":true},{"id":"c2","axis":"Consentement","text":"L’organisme peut-il prouver chaque consentement et sa version d’information ?","ref":"Art. 7.1","proof":"Journaux horodatés et versions","action":"Conserver une preuve granulaire.","level":2,"critical":false},{"id":"c3","axis":"Consentement","text":"Le retrait est-il aussi simple que le recueil ?","ref":"Art. 7.3","proof":"Lien de retrait, centre de préférences","action":"Simplifier et tester le retrait.","level":2,"critical":false},{"id":"s1","axis":"Sous-traitance","text":"Tous les sous-traitants sont-ils recensés et évalués avant engagement ?","ref":"Art. 28.1","proof":"Liste, questionnaires, audits","action":"Créer une procédure d'évaluation.","level":1,"critical":true},{"id":"s2","axis":"Sous-traitance","text":"Les contrats contiennent-ils les clauses de l’article 28.3 ?","ref":"Art. 28.3","proof":"Contrats et annexes DPA","action":"Mettre à niveau les clauses.","level":1,"critical":true},{"id":"s3","axis":"Sous-traitance","text":"Les sous-traitants ultérieurs sont-ils autorisés et suivis ?","ref":"Art. 28.2, 28.4","proof":"Listes, notifications, autorisations","action":"Encadrer toute la chaîne de sous-traitance.","level":2,"critical":false},{"id":"se1","axis":"Sécurité","text":"Une analyse de risques détermine-t-elle les mesures de sécurité adaptées ?","ref":"Art. 24, 32","proof":"Analyse de risques, plan de traitement","action":"Réaliser une analyse de risques.","level":1,"critical":true},{"id":"se2","axis":"Sécurité","text":"Les accès suivent-ils le moindre privilège et une revue périodique ?","ref":"Art. 25, 32","proof":"Matrice d'habilitation, revues","action":"Formaliser les habilitations et revues.","level":2,"critical":true},{"id":"se3","axis":"Sécurité","text":"MFA, chiffrement et sauvegardes sont-ils adaptés aux risques ?","ref":"Art. 32","proof":"Politiques, configurations, tests","action":"Renforcer les contrôles prioritaires.","level":2,"critical":false},{"id":"v1","axis":"Violations","text":"Une procédure de gestion des violations est-elle opérationnelle ?","ref":"Art. 33, 34","proof":"Procédure, rôles, exercice","action":"Établir et tester la procédure.","level":1,"critical":true},{"id":"v2","axis":"Violations","text":"Toutes les violations sont-elles consignées, même non notifiées ?","ref":"Art. 33.5","proof":"Registre des violations","action":"Créer et tenir le registre.","level":2,"critical":false},{"id":"v3","axis":"Violations","text":"L’organisme sait-il évaluer le risque et notifier sous 72 h ?","ref":"Art. 33.1","proof":"Grille de risque, modèles, exercice","action":"Tester l'escalade sous 72 h.","level":1,"critical":true},{"id":"a1","axis":"AIPD & privacy by design","text":"Les traitements à risque élevé sont-ils identifiés ?","ref":"Art. 35","proof":"Grille de screening, liste CNIL","action":"Instaurer un test d'éligibilité AIPD.","level":1,"critical":true},{"id":"a2","axis":"AIPD & privacy by design","text":"Les AIPD requises sont-elles menées avant mise en œuvre et révisées ?","ref":"Art. 35","proof":"AIPD, avis DPO, dates de revue","action":"Réaliser et tenir à jour les AIPD.","level":2,"critical":true},{"id":"a3","axis":"AIPD & privacy by design","text":"La protection des données dès la conception est-elle intégrée aux projets ?","ref":"Art. 25","proof":"Checklist, exigences, recette","action":"Ajouter des jalons privacy by design.","level":2,"critical":false},{"id":"h1","axis":"Transferts hors EEE","text":"Les transferts hors EEE, y compris accès distants, sont-ils identifiés ?","ref":"Art. 44","proof":"Registre, cartographie, contrats cloud","action":"Cartographier destinations et mécanismes.","level":1,"critical":true},{"id":"h2","axis":"Transferts hors EEE","text":"Chaque transfert repose-t-il sur un mécanisme valide ?","ref":"Art. 45 à 49","proof":"Adéquation, CCT, BCR, dérogation","action":"Sécuriser juridiquement chaque transfert.","level":2,"critical":true}];
const modes={express:['Diagnostic express','10 essentiels · 5 à 8 min',1],complet:['Auto-évaluation complète','28 contrôles · 25 à 40 min',2],audit:['Audit professionnel','40 contrôles · preuves et traçabilité',3]};
const AM={yes:['Conforme',1,'good'],partial:['Partiel',.5,'warn'],no:['Non conforme',0,'bad'],na:['N/A',0,'muted']};let state={mode:null,started:false,axis:'Tous',search:'',ans:{},notes:{}};try{Object.assign(state,JSON.parse(localStorage.getItem('rgpd-matrix-github')||'{}'))}catch{};state.started=false;state.auditQuestionsLoaded=false;if(location.hash==='#audit')state.mode='audit';
const root=document.querySelector('#root'),esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const logo=()=>'<div class="logo"><b>T</b><span>TWAGIRUMUKIZA <strong>— GRC</strong></span></div>';function save(){localStorage.setItem('rgpd-matrix-github',JSON.stringify(state))}function active(){return Qs.filter(q=>state.mode&&q.level<=modes[state.mode][2])}function calc(list){const s=list.filter(q=>state.ans[q.id]&&state.ans[q.id]!=='na');return s.length?Math.round(s.reduce((n,q)=>n+AM[state.ans[q.id]][1],0)/s.length*100):0}
function render(){if(!state.started||!state.mode){root.innerHTML='<main class="landing"><nav>'+logo()+'<span class="tag">Outil d’auto-évaluation</span></nav><section class="hero"><b>GOUVERNANCE · RISQUES · CONFORMITÉ</b><h1>Mesurez votre conformité.<br><em>Agissez avec méthode.</em></h1><p>Une matrice structurée sur le RGPD et les recommandations de la CNIL, du diagnostic rapide à l’audit documenté.</p><div class="trust">✓ Score par axe　 ✓ Écarts prioritaires　 ✓ Plan d’action　 ✓ Sauvegarde sur cet appareil</div></section><section class="modeGrid">'+Object.keys(modes).map((m,i)=>'<button data-mode="'+m+'" class="'+(state.mode===m?'selected':'')+'"><small>0'+(i+1)+'</small><h2>'+modes[m][0]+'</h2><p>'+modes[m][1]+'</p><i>→</i>'+(m==='complet'?'<b>RECOMMANDÉ</b>':'')+'</button>').join('')+'</section><div class="start"><button id="start" '+(!state.mode?'disabled':'')+'>Commencer l’évaluation　→</button><small>Diagnostic indicatif — ne constitue pas un avis juridique.</small></div><footer>Conçu par <strong>Twagirumukiza</strong> · Référentiel CNIL / RGPD</footer></main>';bindLanding();return}const qs=active(),score=calc(qs),done=qs.filter(q=>state.ans[q.id]).length,crit=qs.filter(q=>q.critical&&state.ans[q.id]==='no').length,rows=A.map(name=>({name,list:qs.filter(q=>q.axis===name),score:calc(qs.filter(q=>q.axis===name))})),filtered=qs.filter(q=>(state.axis==='Tous'||q.axis===state.axis)&&(q.text+q.ref).toLowerCase().includes(state.search.toLowerCase()));
root.innerHTML='<main class="app"><header>'+logo()+'<div><button id="print">Imprimer</button><button id="reset">Réinitialiser</button><button id="close">×</button></div></header><div class="shell"><aside><div class="score"><div style="--p:'+score*3.6+'deg"><span>'+score+'<small>%</small></span></div><p><b>Niveau global</b><strong class="'+(score>=75?'good':score>=50?'warn':'bad')+'">'+(score>=75?'Maîtrisé':score>=50?'À renforcer':'Insuffisant')+'</strong></p></div><label>Progression <b>'+done+'/'+qs.length+'</b></label><progress value="'+done+'" max="'+qs.length+'"></progress>'+(crit?'<p class="alert">⚠ '+crit+' écart(s) critique(s)</p>':'')+'<nav><button data-axis="Tous" class="'+(state.axis==='Tous'?'on':'')+'">Vue d’ensemble <b>'+score+'%</b></button>'+rows.map(r=>'<button data-axis="'+esc(r.name)+'" class="'+(state.axis===r.name?'on':'')+'"><span>'+esc(r.name)+'<small>'+r.list.filter(q=>state.ans[q.id]).length+'/'+r.list.length+' évalués</small></span><b>'+r.score+'%</b></button>').join('')+'</nav><button class="back" id="back">← Changer de parcours</button></aside><section class="content"><div class="head"><div><small>'+modes[state.mode][0]+'</small><h1>'+(state.axis==='Tous'?'Matrice de conformité':esc(state.axis))+'</h1><p>Évaluez chaque exigence et documentez vos preuves.</p></div><input id="search" value="'+esc(state.search)+'" placeholder="Rechercher une exigence…"></div>'+(state.axis==='Tous'?'<div class="summary">'+rows.map(r=>'<button data-axis="'+esc(r.name)+'"><span><b>'+esc(r.name)+'</b><small>'+r.list.filter(q=>state.ans[q.id]).length+'/'+r.list.length+'</small></span><strong>'+r.score+'%</strong><i><em style="width:'+r.score+'%"></em></i></button>').join('')+'</div>':'')+'<div class="legend">● Conforme　● Partiel　● Non conforme　● N/A</div>'+filtered.map(q=>'<article class="'+(state.ans[q.id]||'')+'"><div class="q"><span>'+String(qs.indexOf(q)+1).padStart(2,'0')+'</span><div><small>'+esc(q.axis)+'　<a href="https://eur-lex.europa.eu/eli/reg/2016/679/oj" target="_blank">'+esc(q.ref)+'</a>'+(q.critical?'<b> CRITIQUE</b>':'')+'</small><h3>'+esc(q.text)+'</h3></div></div><div class="answers">'+Object.keys(AM).map(a=>'<button data-answer="'+a+'" data-id="'+q.id+'" class="'+(state.ans[q.id]===a?AM[a][2]:'')+'">○ '+AM[a][0]+'</button>').join('')+'</div><details><summary>Preuve, observation et recommandation　＋</summary><div><section><label>Preuves attendues</label><p>'+esc(q.proof)+'</p><label>Observation de l’auditeur</label><textarea data-note="'+q.id+'" placeholder="Document observé, écart, responsable…">'+esc(state.notes[q.id])+'</textarea></section><section><label>Action recommandée</label><p>'+esc(q.action)+'</p><small>Priorité : '+(q.critical?'immédiate':'à planifier')+'</small></section></div></details></article>').join('')+'<div class="report"><div><small>SYNTHÈSE</small><h2>Votre plan d’action se construit automatiquement.</h2><p>'+qs.filter(q=>state.ans[q.id]==='no'||state.ans[q.id]==='partial').length+' action(s), dont '+crit+' critique(s).</p></div><button id="pdf">Générer le rapport PDF →</button></div><p class="legal">Référentiel indicatif fondé sur le <a href="https://www.cnil.fr/fr/reglement-europeen-protection-donnees" target="_blank">RGPD et les ressources de la CNIL</a>.</p></section></div></main>';bindApp()}
function bindLanding(){document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{state.mode=b.dataset.mode;save();render()});const s=document.querySelector('#start');if(s)s.onclick=()=>{state.started=true;render()}}
function bindApp(){document.querySelectorAll('[data-axis]').forEach(b=>b.onclick=()=>{state.axis=b.dataset.axis;render()});document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{state.ans[b.dataset.id]=b.dataset.answer;save();render()});document.querySelectorAll('[data-note]').forEach(t=>t.oninput=()=>{state.notes[t.dataset.note]=t.value;save()});document.querySelector('#search').oninput=e=>{state.search=e.target.value;render()};document.querySelector('#print').onclick=document.querySelector('#pdf').onclick=printComplianceReport;document.querySelector('#close').onclick=document.querySelector('#back').onclick=()=>{state.started=false;render()};document.querySelector('#reset').onclick=()=>{if(confirm('Effacer toutes les réponses ?')){state.ans={};state.notes={};save();render()}}}const baseRender=render;render=function(){baseRender();injectContact()};

function reportVocabulary(){const en=state.lang==='en';return en?{title:'GDPR compliance report',subtitle:'Detailed self-assessment and operational action plan',preparedFor:'Prepared for',part1:'Part 1 — Detailed assessment results',part1Intro:'Each requirement is shown with the client’s declared answer. An auditor note appears only when it has actually been entered.',part2:'Part 2 — Actions to manage',part2Intro:'This plan includes every partial, non-compliant or unanswered requirement. Each action states the gap, what to do, the expected result, the evidence and the completion criterion.',answer:'Client answer',observation:'Client observation',gap:'Identified gap',recommendation:'Recommendation',how:'In practice',result:'Expected result',proof:'Evidence required',done:'Action completed when',priority:'Priority',immediate:'Immediate',planned:'Planned',noActions:'No corrective action was generated from the answers provided.',disclaimer:'Indicative self-assessment based on the GDPR and CNIL resources. It does not replace an evidence-based audit or tailored legal advice.',answers:{yes:'Compliant',partial:'Partially compliant',no:'Non-compliant',na:'N/A',empty:'Unanswered'}}:{title:'Rapport de conformité RGPD',subtitle:'Auto-évaluation détaillée et plan d’action opérationnel',preparedFor:'Préparé pour',part1:'Première partie — Résultats détaillés de l’évaluation',part1Intro:'Chaque exigence est présentée avec la réponse déclarée par le client. Une observation n’apparaît que lorsqu’elle a réellement été renseignée.',part2:'Deuxième partie — Actions à piloter',part2Intro:'Ce plan reprend chaque exigence partielle, non conforme ou non renseignée. Pour chaque action, il précise l’écart, la conduite à tenir, le résultat attendu, les preuves et le critère de clôture.',answer:'Réponse du client',observation:'Observation du client',gap:'Écart constaté',recommendation:'Recommandation',how:'Concrètement',result:'Résultat attendu',proof:'Preuves nécessaires',done:'Action terminée lorsque',priority:'Priorité',immediate:'Immédiate',planned:'À planifier',noActions:'Aucune action corrective n’a été générée à partir des réponses fournies.',disclaimer:'Auto-évaluation indicative fondée sur le RGPD et les ressources de la CNIL. Elle ne remplace ni un audit fondé sur des preuves ni un conseil juridique adapté.',answers:{yes:'Conforme',partial:'Partiellement conforme',no:'Non conforme',na:'N/A',empty:'Non renseignée'}}}

const REPORT_STEPS={"g1":{"fr":"Nommer officiellement le pilote RGPD, préciser son périmètre, son temps disponible, ses relais et son reporting. Faire valider une lettre de mission et un RACI par la direction.","en":"Formally appoint the GDPR lead, define scope, available time, relays and reporting. Have management approve a mission letter and a RACI."},"g2":{"fr":"Documenter l’analyse des critères de désignation obligatoire. Si un DPO est requis, le nommer, garantir son indépendance, publier ses coordonnées et notifier la CNIL.","en":"Document the assessment of mandatory appointment criteria. If required, appoint an independent DPO, publish contact details and notify the authority."},"g4":{"fr":"Définir un parcours de sensibilisation à l’arrivée puis périodique, adapté aux métiers exposés. Enregistrer les participations et vérifier les acquis par un quiz ou un exercice.","en":"Provide induction and periodic awareness tailored to exposed roles. Record attendance and verify understanding through a quiz or exercise."},"r1":{"fr":"Recenser les traitements avec les responsables métiers, rapprocher le registre des applications et contrats, puis faire valider chaque fiche datée par son propriétaire.","en":"Inventory processing with business owners, reconcile the register with systems and contracts, then have each dated record approved by its owner."},"r2":{"fr":"Reprendre chaque fiche du registre avec une grille unique et compléter finalités, catégories de données et de personnes, destinataires, transferts, durées et mesures de sécurité.","en":"Review every register record with one checklist and complete purposes, data subjects, data, recipients, transfers, retention and security fields."},"p1":{"fr":"Pour chaque finalité, choisir et justifier une base légale distincte. Traiter séparément les données sensibles et faire valider les cas ambigus avant la collecte.","en":"Choose and justify a separate legal basis for each purpose. Address sensitive data separately and validate ambiguous cases before collection."},"p2":{"fr":"Passer en revue formulaires, imports, API et champs libres avec les métiers. Supprimer ou rendre facultative toute donnée qui n’est pas nécessaire à la finalité annoncée.","en":"Review forms, imports, APIs and free-text fields with business teams. Remove or make optional any data not necessary for the stated purpose."},"p3":{"fr":"Créer un référentiel de conservation par catégorie de données avec durée active, archivage et sort final. Paramétrer les purges et contrôler leur exécution dans les systèmes et sauvegardes.","en":"Create a retention schedule with active period, archive and final outcome. Configure deletion and monitor execution across systems and backups."},"p4":{"fr":"Imposer une validation avant toute réutilisation des données. Comparer la nouvelle finalité à l’information initiale, la base légale, les attentes des personnes et les risques.","en":"Require approval before any data reuse. Compare the new purpose with initial notice, legal basis, individual expectations and risks."},"t1":{"fr":"Identifier chaque point de collecte et associer une mention courte accessible au bon moment, avec un renvoi vers l’information complète. Tester le parcours sur tous les supports.","en":"Identify every collection point and display a timely short notice linking to full information. Test the journey across all channels."},"t2":{"fr":"Contrôler les mentions avec une grille couvrant identité, finalités, bases légales, destinataires, transferts, durées, droits, réclamation et origine des données.","en":"Check notices against identity, purposes, legal bases, recipients, transfers, retention, rights, complaints and data source requirements."},"t3":{"fr":"Créer un canal unique de réception, une procédure d’identification et un calendrier de traitement. Prévoir les modèles de réponse, les exceptions et l’escalade avant l’échéance d’un mois.","en":"Set one intake channel, an identity-check procedure and a handling timeline. Prepare response templates, exceptions and escalation before the one-month deadline."},"c1":{"fr":"Revoir chaque parcours de consentement : choix séparés, action positive, information compréhensible et absence de case précochée ou de pression. Tester le refus autant que l’acceptation.","en":"Review each consent journey for separate choices, positive action, clear information and no pre-ticked box or pressure. Test refusal as well as acceptance."},"c2":{"fr":"Enregistrer pour chaque consentement la personne, la finalité, le choix, l’horodatage, la source et la version exacte de l’information présentée.","en":"Record the person, purpose, choice, timestamp, source and exact information version for every consent."},"c3":{"fr":"Ajouter un retrait visible dans le même canal que le recueil, sans étapes supplémentaires injustifiées. Propager le retrait à tous les outils et conserver la trace de son exécution.","en":"Provide a visible withdrawal in the same channel without unjustified extra steps. Propagate it to every system and keep execution evidence."},"s1":{"fr":"Centraliser la liste des sous-traitants et instaurer une évaluation avant signature portant sur sécurité, localisation, sous-traitance ultérieure, incidents et garanties.","en":"Centralise the processor list and assess security, location, subprocessors, incidents and safeguards before signature."},"s2":{"fr":"Comparer chaque contrat à la liste des clauses de l’article 28.3. Ajouter ou renégocier un DPA signé et cohérent avec le service réellement fourni.","en":"Compare every contract with Article 28(3). Add or renegotiate a signed DPA consistent with the service actually delivered."},"s3":{"fr":"Obtenir et maintenir la liste des sous-traitants ultérieurs, leurs lieux de traitement et le mécanisme d’autorisation. Organiser les notifications de changement et le droit d’opposition.","en":"Maintain the subprocessor list, processing locations and authorisation mechanism. Organise change notices and objection rights."},"se1":{"fr":"Identifier menaces, vulnérabilités, impacts et vraisemblance pour les traitements prioritaires. Décider les mesures, responsables, échéances et risques résiduels acceptés.","en":"Identify threats, vulnerabilities, impacts and likelihood for priority processing. Decide controls, owners, deadlines and accepted residual risks."},"se2":{"fr":"Lister les droits par rôle, supprimer les accès excessifs et instaurer validation, traçabilité et revue périodique. Traiter sans délai les arrivées, mobilités et départs.","en":"List rights by role, remove excessive access and establish approval, traceability and periodic review. Handle joiners, movers and leavers promptly."},"se3":{"fr":"Déployer MFA sur les accès sensibles, chiffrer selon les risques et définir des sauvegardes isolées. Réaliser des tests de restauration et conserver les résultats.","en":"Deploy MFA for sensitive access, risk-based encryption and isolated backups. Perform restoration tests and retain results."},"v1":{"fr":"Rédiger une procédure avec critères d’alerte, rôles, canal d’urgence et décisions. Organiser un exercice incluant qualification, confinement, documentation et communication.","en":"Write a procedure with alert criteria, roles, emergency channel and decisions. Exercise qualification, containment, documentation and communication."},"v2":{"fr":"Consigner tout incident impliquant des données, même sans notification : faits, effets, données concernées, mesures prises, analyse de risque et décision motivée.","en":"Log every personal-data incident, even when not notified: facts, effects, data, measures, risk assessment and reasoned decision."},"v3":{"fr":"Mettre en place une grille de gravité et démarrer l’horloge de 72 heures dès la connaissance de la violation. Tester l’escalade et préparer le formulaire de notification.","en":"Use a severity matrix and start the 72-hour clock when the breach becomes known. Test escalation and prepare the notification form."},"a1":{"fr":"Ajouter un test AIPD à l’entrée de chaque projet en s’appuyant sur les critères et listes de la CNIL. Conserver la décision et sa justification.","en":"Add a DPIA screening test at project intake using authority criteria and lists. Retain the decision and justification."},"a2":{"fr":"Lancer l’AIPD avant mise en œuvre, associer métiers, sécurité et DPO, traiter les risques puis fixer une date de revue lors de tout changement significatif.","en":"Run the DPIA before implementation with business, security and DPO input, treat risks and set review dates for significant changes."},"a3":{"fr":"Insérer des exigences vie privée dans cadrage, conception, recette et mise en production. Vérifier minimisation, réglages protecteurs, accès, conservation et information.","en":"Embed privacy requirements in scoping, design, testing and production. Check minimisation, protective defaults, access, retention and notices."},"h1":{"fr":"Recenser pays de destination, hébergeurs, support à distance, accès administrateurs et chaîne de sous-traitance. Relier chaque transfert au traitement concerné.","en":"Inventory destination countries, hosting, remote support, administrator access and processor chains. Link every transfer to its processing activity."},"h2":{"fr":"Associer à chaque transfert une décision d’adéquation, des CCT, des BCR ou une dérogation strictement justifiée. Vérifier signature, version et périmètre.","en":"Assign adequacy, SCCs, BCRs or a strictly justified derogation to every transfer. Check signature, version and scope."}};

function reportGap(q,value,en){const action=q.action.replace(/\.$/,'').toLowerCase();if(en){if(value==='partial')return 'The answer “Partially compliant” shows that the requirement is not fully covered. The remaining gap concerns complete implementation or evidence of the following action: '+action+'.';if(value==='no')return 'No sufficient measure is declared for this requirement. The organisation must therefore '+action+'.';return 'The situation has not been described. The organisation must first verify the actual practice and available evidence, then '+action+'.'}if(value==='partial')return 'La réponse « Partiellement conforme » montre que l’exigence n’est pas entièrement couverte. L’écart restant porte sur la mise en œuvre complète ou la preuve de l’action suivante : '+action+'.';if(value==='no')return 'Aucun dispositif suffisant n’est déclaré pour cette exigence. L’organisme doit donc '+action+'.';return 'La situation n’est pas renseignée. L’organisme doit d’abord vérifier la pratique réelle et les preuves disponibles, puis '+action+'.'}

function reportHow(q,value,en){const step=REPORT_STEPS[q.id];if(step)return en?step.en:step.fr;return (en?'Assign an owner and deadline. ':'Désignez un responsable et une échéance. ')+q.action}

function reportExpected(q,en){const requirement=q.text.replace(/\?$/,'');return en?'The requirement is demonstrably met: “'+requirement+'”. The practice is consistent in day-to-day operations.':'L’exigence est respectée de manière démontrable : « '+requirement+' ». La pratique est constante dans les opérations courantes.'}

function reportDone(q,en){const proof=q.proof.replace(/^./,c=>c.toLowerCase());return en?'The following evidence is available, dated and approved: '+proof+'. A sample check confirms that the measure is actually applied.':'Les preuves suivantes sont disponibles, datées et validées : '+proof+'. Un contrôle sur échantillon confirme que la mesure est réellement appliquée.'}

function buildComplianceReport(){
 const en=state.lang==='en',v=reportVocabulary(),qs=active(),score=calc(qs),done=qs.filter(q=>state.ans[q.id]).length;
 const critical=qs.filter(q=>q.critical&&(state.ans[q.id]==='no'||state.ans[q.id]==='partial')).length;
 const actions=qs.filter(q=>!state.ans[q.id]||state.ans[q.id]==='partial'||state.ans[q.id]==='no');
 const date=new Intl.DateTimeFormat(en?'en-GB':'fr-FR',{dateStyle:'long'}).format(new Date());
 const reference=state.reportId||('RGPD-'+new Date().getFullYear()+'-'+Math.random().toString(36).slice(2,8).toUpperCase());
 const lead=state.lead||{},clientName=String(lead.name||lead.fullName||'').trim(),clientOrg=String(lead.org||lead.organisation||'').trim(),clientRole=String(lead.role||lead.roleTitle||'').trim();
 const answerLabel=q=>v.answers[state.ans[q.id]||'empty'];
 const clientBlock=clientName||clientOrg?'<div class="print-client"><small>'+v.preparedFor+'</small>'+(clientName?'<strong>'+esc(clientName)+'</strong>':'')+(clientOrg||clientRole?'<span>'+[clientOrg,clientRole].filter(Boolean).map(esc).join(' · ')+'</span>':'')+'</div>':'';
 const details=qs.map((q,i)=>{
  const value=state.ans[q.id]||'empty',note=String(state.notes[q.id]||'').trim();
  return '<article class="print-question status-'+value+'"><div class="print-question-head"><span>'+String(i+1).padStart(2,'0')+'</span><div><small>'+esc(q.axis)+' · '+esc(q.ref)+(q.critical?' · '+(en?'CRITICAL':'CRITIQUE'):'')+'</small><h3>'+esc(q.text)+'</h3></div></div><p class="print-answer"><b>'+v.answer+' :</b> '+answerLabel(q)+'</p>'+(note?'<p class="print-note"><b>'+v.observation+' :</b> '+esc(note)+'</p>':'')+'</article>';
 }).join('');
 const actionItems=actions.map((q,i)=>{
  const value=state.ans[q.id]||'empty',note=String(state.notes[q.id]||'').trim();
  return '<article class="print-action"><header><span>'+String(i+1).padStart(2,'0')+'</span><div><small>'+esc(q.axis)+' · '+esc(q.ref)+'</small><h3>'+esc(q.text)+'</h3></div><strong>'+(q.critical?v.immediate:v.planned)+'</strong></header><dl><div><dt>'+v.answer+'</dt><dd>'+answerLabel(q)+'</dd></div>'+(note?'<div><dt>'+v.observation+'</dt><dd>'+esc(note)+'</dd></div>':'')+'<div><dt>'+v.gap+'</dt><dd>'+esc(reportGap(q,value,en))+'</dd></div><div><dt>'+v.recommendation+'</dt><dd>'+esc(q.action)+'</dd></div><div><dt>'+v.how+'</dt><dd>'+esc(reportHow(q,value,en))+'</dd></div><div><dt>'+v.result+'</dt><dd>'+esc(reportExpected(q,en))+'</dd></div><div><dt>'+v.proof+'</dt><dd>'+esc(q.proof)+'</dd></div><div><dt>'+v.done+'</dt><dd>'+esc(reportDone(q,en))+'</dd></div></dl></article>';
 }).join('');
 const report=document.createElement('section');report.className='print-report';
 report.innerHTML='<header class="print-cover"><div class="print-brand"><b>TW</b><span>TWAGIRUMUKIZA — GRC</span></div><p>GOUVERNANCE · RISQUES · CONFORMITÉ</p><h1>'+v.title+'</h1><h2>'+v.subtitle+'</h2>'+clientBlock+'<div class="print-meta"><span><b>'+(en?'Reference':'Référence')+'</b>'+esc(reference)+'</span><span><b>'+(en?'Date':'Date')+'</b>'+date+'</span><span><b>'+(en?'Path':'Parcours')+'</b>'+esc(modes[state.mode][0])+'</span></div><div class="print-score"><strong>'+score+'%</strong><span>'+(en?'Overall score':'Score global')+'<br>'+done+'/'+qs.length+' '+(en?'answered':'renseignées')+' · '+critical+' '+(en?'critical gaps':'écarts critiques')+'</span></div><p class="print-disclaimer">'+v.disclaimer+'</p></header><section class="print-part page-start"><div class="print-part-title"><small>01</small><h2>'+v.part1+'</h2><p>'+v.part1Intro+'</p></div>'+details+'</section><section class="print-part page-start"><div class="print-part-title"><small>02</small><h2>'+v.part2+'</h2><p>'+v.part2Intro+'</p></div>'+(actionItems||'<p class="print-empty">'+v.noActions+'</p>')+'</section><footer class="print-footer">© '+new Date().getFullYear()+' Twagirumukiza · '+esc(reference)+'</footer>';
 return report;
}

function printComplianceReport(){document.querySelector('.print-report')?.remove();const report=buildComplianceReport();document.body.appendChild(report);document.body.classList.add('printing-report');let cleaned=false;const cleanup=()=>{if(cleaned)return;cleaned=true;document.body.classList.remove('printing-report');report.remove();window.removeEventListener('afterprint',cleanup)};window.addEventListener('afterprint',cleanup);setTimeout(()=>window.print(),80);setTimeout(cleanup,120000)}
function injectContact(){
 const wrap=document.createElement('div');wrap.innerHTML='<div class="support-bar"><div><small>UN ÉCART À TRAITER ?</small><b>Transformez votre diagnostic en plan d’action.</b></div><div><button class="support-mail">M’envoyer un e-mail</button><button class="support-calcom" data-cal-link="innocent-twagirumukiza/analyse-personnalisee" data-cal-namespace="analyse-personnalisee" data-cal-config=\'{"layout":"month_view","useSlotsViewOnSmallScreen":"true"}\'>Réserver directement — Cal.com</button></div></div>';
 root.appendChild(wrap);
 wrap.querySelector('.support-mail').onclick=()=>mailOffer('Demande d’accompagnement — Conformité RGPD',['Bonjour Innocent,','','Je souhaite être accompagné(e) dans ma démarche de conformité RGPD.','','Contexte / besoin :','','Cordialement,']);
}
