const EN_DATA={"g1":["Is someone formally responsible for GDPR compliance?","Letter of appointment, RACI, reporting","Appoint a lead and formalise their responsibilities."],"g2":["Has a DPO been appointed where this is mandatory?","Mandatory-assessment record, CNIL notification","Assess the requirement and appoint a DPO where necessary."],"g4":["Are staff regularly trained and made aware of data protection?","Plan, materials and training records","Provide initial and periodic awareness training."],"r1":["Does an up-to-date record of processing activities exist?","Dated record and change history","Create or update the record of processing activities."],"r2":["Does each record specify purposes, data, people, recipients and retention periods?","Complete and approved processing records","Complete every mandatory field."],"p1":["Is a valid lawful basis defined for each purpose?","Processing record and legal analysis","Document one lawful basis for each purpose."],"p2":["Is the personal data collected strictly necessary?","Review of forms and data fields","Remove unnecessary data collection."],"p3":["Are precise retention periods defined and applied?","Policy, archiving rules, deletion logs","Define and enforce archiving and deletion."],"p4":["Are purposes defined before collection and further uses controlled?","Project records, compatibility tests","Formally approve every new purpose."],"t1":["Do individuals receive clear information at the appropriate time?","Notices, forms and screens","Update and deploy privacy notices."],"t2":["Do privacy notices contain all mandatory information?","Privacy-notice review checklist","Check lawful bases, periods, rights and recipients."],"t3":["Can rights requests be handled within one month?","Procedure, request log, templates","Formalise receipt, assessment and response."],"c1":["Where used, is consent freely given, specific, informed and unambiguous?","Forms, journeys and settings","Correct consent-collection mechanisms."],"c2":["Can the organisation prove each consent and the information version shown?","Timestamped logs and notice versions","Retain granular evidence of consent."],"c3":["Is withdrawing consent as easy as giving it?","Withdrawal link, preference centre","Simplify and test consent withdrawal."],"s1":["Are all processors listed and assessed before engagement?","List, questionnaires and audits","Create a supplier-assessment procedure."],"s2":["Do contracts contain all clauses required by Article 28(3)?","Contracts and data-processing agreements","Update processor clauses."],"s3":["Are sub-processors authorised and monitored?","Lists, notices and authorisations","Govern the entire processing chain."],"se1":["Does a risk assessment determine appropriate security measures?","Risk assessment, treatment plan","Carry out a risk assessment."],"se2":["Do access rights follow least privilege and periodic review?","Access matrix and review records","Formalise access rights and reviews."],"se3":["Are MFA, encryption and backups proportionate to the risks?","Policies, configurations and tests","Strengthen priority security controls."],"v1":["Is an operational personal-data breach procedure in place?","Procedure, roles and exercise","Establish and test the breach procedure."],"v2":["Are all breaches recorded, including those not notified?","Personal-data breach register","Create and maintain the breach register."],"v3":["Can the organisation assess risk and notify within 72 hours?","Risk grid, templates and exercise","Test escalation and notification within 72 hours."],"a1":["Are processing operations likely to result in high risk identified?","Screening grid, CNIL list","Introduce systematic DPIA screening."],"a2":["Are required DPIAs completed before processing and kept under review?","DPIAs, DPO advice, review dates","Complete and maintain the required DPIAs."],"a3":["Is data protection by design integrated into projects?","Checklist, requirements and acceptance tests","Add privacy-by-design project checkpoints."],"h1":["Are transfers outside the EEA, including remote access, identified?","Processing record, mapping, cloud contracts","Map destinations and transfer mechanisms."],"h2":["Does every transfer rely on a valid transfer mechanism?","Adequacy decision, SCCs, BCRs, derogation","Provide a lawful safeguard for every transfer."]};
const UI_EN={
'Outil d’auto-évaluation':'Self-assessment tool','GOUVERNANCE · RISQUES · CONFORMITÉ':'GOVERNANCE · RISK · COMPLIANCE','Mesurez votre conformité.':'Measure your compliance.','Agissez avec méthode.':'Act methodically.','Une matrice structurée sur le RGPD et les recommandations de la CNIL, du diagnostic rapide à l’audit documenté.':'A GDPR and CNIL-based matrix, from a quick check to a documented audit.','✓ Score par axe　 ✓ Écarts prioritaires　 ✓ Plan d’action　 ✓ Sauvegarde sur cet appareil':'✓ Score by area　 ✓ Priority gaps　 ✓ Action plan　 ✓ Saved on this device','Diagnostic express':'Quick assessment','10 essentiels · 5 à 8 min':'10 essentials · 5 to 8 min','Auto-évaluation complète':'Full self-assessment','28 contrôles · 25 à 40 min':'28 checks · 25 to 40 min','Audit professionnel':'Professional audit','40 contrôles · preuves et traçabilité':'40 checks · evidence and traceability','RECOMMANDÉ':'RECOMMENDED','Commencer l’évaluation　→':'Start assessment　→','Diagnostic indicatif — ne constitue pas un avis juridique.':'Indicative assessment — not legal advice.','Conçu par Twagirumukiza · Référentiel CNIL / RGPD':'Designed by Twagirumukiza · CNIL / GDPR framework','Imprimer':'Print','Réinitialiser':'Reset','Niveau global':'Overall level','Maîtrisé':'Controlled','À renforcer':'Needs improvement','Insuffisant':'Insufficient','Progression':'Progress','Vue d’ensemble':'Overview','évalués':'assessed','Changer de parcours':'Change pathway','Matrice de conformité':'Compliance matrix','Évaluez chaque exigence et documentez vos preuves.':'Assess each requirement and document your evidence.','Rechercher une exigence…':'Search a requirement…','Conforme':'Compliant','Partiel':'Partial','Non conforme':'Non-compliant','Preuve, observation et recommandation　＋':'Evidence, observation and recommendation　＋','Preuves attendues':'Expected evidence','Observation de l’auditeur':'Auditor observation','Document observé, écart, responsable…':'Document reviewed, gap, owner…','Action recommandée':'Recommended action','Priorité : immédiate':'Priority: immediate','Priorité : à planifier':'Priority: to be planned','SYNTHÈSE':'SUMMARY','Votre plan d’action se construit automatiquement.':'Your action plan is built automatically.','Générer le rapport PDF →':'Generate PDF report →','UN ÉCART À TRAITER ?':'A GAP TO ADDRESS?','Transformez votre diagnostic en plan d’action.':'Turn your assessment into an action plan.','M’envoyer un e-mail':'Email me','Prendre rendez-vous':'Book a meeting','ACCOMPAGNEMENT RGPD':'GDPR SUPPORT','Parlons de votre conformité.':'Let’s discuss your compliance.','Choisissez un créneau d’1 heure. Votre messagerie s’ouvrira ensuite avec la demande préremplie.':'Choose a 1-hour slot. Your email app will then open with a pre-filled request.','01 — Choisir une date':'01 — Choose a date','02 — Choisir un horaire':'02 — Choose a time','Votre nom *':'Your name *','Votre e-mail *':'Your email *','Sélectionnez une date et un horaire.':'Select a date and time.','Demander ce rendez-vous':'Request this meeting','Ou écrivez directement à':'Or email','écart(s) critique(s)':'critical gap(s)','action(s), dont':'action(s), including','critique(s).':'critical.','CRITIQUE':'CRITICAL','Réserver directement — Cal.com':'Book directly — Cal.com'};
const FR_AXES=[...A],EN_AXES=['Governance','Processing records','Core principles','Transparency & rights','Consent','Processors','Security','Data breaches','DPIA & privacy by design','Transfers outside the EEA'];
Qs.forEach(q=>q._fr={axis:q.axis,text:q.text,proof:q.proof,action:q.action});
function applyLanguageData(){const en=state.lang==='en';Qs.forEach(q=>{const d=q._fr;if(en){const t=EN_DATA[q.id];q.axis=EN_AXES[FR_AXES.indexOf(d.axis)];q.text=t[0];q.proof=t[1];q.action=t[2]}else Object.assign(q,d)});A.splice(0,A.length,...(en?EN_AXES:FR_AXES));modes.express[0]=en?'Quick assessment':'Diagnostic express';modes.complet[0]=en?'Full self-assessment':'Auto-évaluation complète';modes.audit[0]=en?'Professional audit':'Audit professionnel';AM.yes[0]=en?'Compliant':'Conforme';AM.partial[0]=en?'Partial':'Partiel';AM.no[0]=en?'Non-compliant':'Non conforme'}
function translateUI(){if(state.lang!=='en')return;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;while(n=walker.nextNode()){const raw=n.nodeValue,trim=raw.trim();if(UI_EN[trim])n.nodeValue=raw.replace(trim,UI_EN[trim]);else{for(const [fr,en] of Object.entries(UI_EN))if(raw.includes(fr)){n.nodeValue=raw.replaceAll(fr,en);break}}}root.querySelectorAll('input,textarea').forEach(e=>{if(UI_EN[e.placeholder])e.placeholder=UI_EN[e.placeholder]});document.documentElement.lang='en'}
function injectUtilities(){const host=document.querySelector('.landing nav,.app header');if(!host)return;let tools=document.createElement('div');tools.className='utility-tools';tools.innerHTML='<button data-util="lang" title="Français / English">'+(state.lang==='en'?'FR':'EN')+'</button><button data-util="theme" title="Clair / Obscur">'+(state.theme==='light'?'◐':'☀')+'</button><span class="font-tools"><button data-size="-1" title="Réduire">A−</button><button data-size="0" title="Taille normale">A</button><button data-size="1" title="Agrandir">A+</button></span>';host.appendChild(tools);tools.querySelector('[data-util=lang]').onclick=()=>{const old=state.lang||'fr';if(state.axis!=='Tous')state.axis=old==='fr'?EN_AXES[FR_AXES.indexOf(state.axis)]:FR_AXES[EN_AXES.indexOf(state.axis)];state.lang=old==='en'?'fr':'en';save();render()};tools.querySelector('[data-util=theme]').onclick=()=>{state.theme=state.theme==='light'?'dark':'light';save();applyPrefs()};tools.querySelectorAll('[data-size]').forEach(b=>b.onclick=()=>{state.fontSize=Math.max(-1,Math.min(2,Number(state.fontSize||0)+Number(b.dataset.size)));if(b.dataset.size==='0')state.fontSize=0;save();applyPrefs()})}
function applyPrefs(){document.body.classList.toggle('light',state.theme==='light');document.documentElement.style.setProperty('--font-scale',String(1+Number(state.fontSize||0)*.12));document.documentElement.lang=state.lang==='en'?'en':'fr'}
if(!state.lang)state.lang='fr';if(!state.theme)state.theme='dark';if(state.fontSize==null)state.fontSize=0;
const v3Render=render;render=function(){applyLanguageData();v3Render();translateUI();injectUtilities();applyPrefs()};render();

