const commercialCopy={fr:{offers:'Choisissez le niveau d’accompagnement adapté',express:'Gratuit · sans inscription',complete:'Gratuit · rapport contre coordonnées',audit:'Réalisé par un auditeur · sur devis',start:'Commencer gratuitement',leadTitle:'Recevez votre auto-évaluation complète',leadText:'Vos coordonnées préparent le rapport et peuvent être enregistrées dans notre backend Supabase afin d’assurer le suivi de votre demande. Un e-mail prérempli peut également s’ouvrir pour vous permettre de confirmer le contact.',submit:'Accéder aux 28 contrôles',analysis:'Faire analyser mes résultats',analysisSub:'Restitution personnalisée · 1 h · feuille de route',auditCta:'Demander un audit fondé sur des preuves',licence:'Découvrir la licence en marque blanche',consent:'J’accepte d’être recontacté au sujet de cette demande.',marketing:'Je souhaite recevoir ponctuellement des ressources RGPD (facultatif).'},en:{offers:'Choose the right level of support',express:'Free · no registration',complete:'Free · report for contact details',audit:'Auditor-led · quotation',start:'Start for free',leadTitle:'Get your full self-assessment',leadText:'Your contact details prepare the report and may be stored in our Supabase backend to manage your request. A pre-filled email may also open so you can confirm the contact.',submit:'Access the 28 checks',analysis:'Get my results analysed',analysisSub:'Personalised review · 1 hour · roadmap',auditCta:'Request an evidence-based audit',licence:'Discover the white-label licence',consent:'I agree to be contacted about this request.',marketing:'I would like to receive occasional GDPR resources (optional).'}};
function mailOffer(subject,lines){const body=lines.join('\n'),url='mailto:inno.twa@gmail.com?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body),trigger=document.activeElement instanceof HTMLElement?document.activeElement:null;if(trigger){trigger.classList.add('mail-pending');trigger.disabled=true}let opened=false;const mark=()=>{opened=true};window.addEventListener('blur',mark,{once:true});document.addEventListener('visibilitychange',mark,{once:true});location.href=url;setTimeout(()=>{window.removeEventListener('blur',mark);document.removeEventListener('visibilitychange',mark);if(trigger&&trigger.isConnected){trigger.classList.remove('mail-pending');trigger.disabled=false}if(!opened)mailFallback(subject,body,url)},1200)}
function mailFallback(subject,body,url){const en=state.lang==='en',full=subject+'\n\n'+body,box=document.createElement('div');box.className='commercial-modal';box.innerHTML='<div class="commercial-dialog mail-fallback"><button type="button" class="commercial-close" aria-label="Fermer">×</button><small>'+(en?'NO EMAIL APP DETECTED':'MESSAGERIE NON DÉTECTÉE')+'</small><h2>'+(en?'We couldn’t open your email app':'Impossible d’ouvrir votre messagerie')+'</h2><p>'+(en?'No default email application was detected on this device. Copy the message below and paste it into your webmail (Gmail, Outlook.com…), or write directly to':'Aucune application e-mail par défaut n’a été détectée sur cet appareil. Copiez le message ci-dessous et collez-le dans votre messagerie web (Gmail, Outlook.com…), ou écrivez directement à')+' <a href="mailto:inno.twa@gmail.com">inno.twa@gmail.com</a>.</p><textarea readonly class="mail-fallback-text"></textarea><div class="mail-fallback-actions"><button type="button" class="commercial-submit" data-copy>'+(en?'Copy the message':'Copier le message')+'</button><a href="'+url+'" class="mail-fallback-retry">'+(en?'Try again':'Réessayer')+'</a></div></div>';box.querySelector('.mail-fallback-text').value=full;document.body.appendChild(box);const close=()=>box.remove();box.querySelector('.commercial-close').onclick=close;box.onclick=e=>{if(e.target===box)close()};const copyBtn=box.querySelector('[data-copy]'),copiedLabel=en?'Copied!':'Copié !',defaultLabel=copyBtn.textContent;copyBtn.onclick=()=>{const done=()=>{copyBtn.textContent=copiedLabel;setTimeout(()=>copyBtn.textContent=defaultLabel,2500)};if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(full).then(done).catch(()=>{const ta=box.querySelector('.mail-fallback-text');ta.select();document.execCommand('copy');done()})}else{const ta=box.querySelector('.mail-fallback-text');ta.select();document.execCommand('copy');done()}}}
function commercialModal(kind){const en=state.lang==='en',c=commercialCopy[en?'en':'fr'],isLead=kind==='lead',box=document.createElement('div');box.className='commercial-modal';box.innerHTML='<form class="commercial-dialog"><button type="button" class="commercial-close" aria-label="Fermer">×</button><small>'+(isLead?'AUTO-ÉVALUATION COMPLÈTE':'AUDIT RGPD PREMIUM')+'</small><h2>'+(isLead?c.leadTitle:(en?'Scope your evidence-based audit':'Cadrons votre audit fondé sur des preuves'))+'</h2><p>'+c.leadText+'</p><div class="lead-grid"><label>'+(en?'Full name':'Nom et prénom')+' *<input name="name" required autocomplete="name"></label><label>'+(en?'Professional email':'E-mail professionnel')+' *<input name="email" required type="email" autocomplete="email"></label><label>'+(en?'Organisation':'Organisation')+' *<input name="org" required autocomplete="organization"></label><label>'+(en?'Role':'Fonction')+' *<input name="role" required></label>'+(isLead?'':'<label>'+(en?'Organisation size':'Taille de l’organisation')+'<select name="size"><option>1–9</option><option>10–49</option><option>50–249</option><option>250+</option></select></label><label>'+(en?'Target timeframe':'Échéance souhaitée')+'<select name="deadline"><option>'+(en?'Under 1 month':'Moins d’un mois')+'</option><option>1–3 mois</option><option>3–6 mois</option></select></label><label class="wide">'+(en?'Context and priority':'Contexte et priorité')+'<textarea name="context"></textarea></label>')+'</div><label class="check"><input name="consent" type="checkbox" required> '+c.consent+' <a href="confidentialite.html">'+(en?'Privacy policy':'Politique de confidentialité')+'</a></label>'+(isLead?'<label class="check"><input name="marketing" type="checkbox"> '+c.marketing+'</label>':'')+'<button class="commercial-submit">'+(isLead?c.submit:(en?'Prepare my audit request':'Préparer ma demande d’audit'))+' →</button><p class="form-note"></p></form>';document.body.appendChild(box);const close=()=>box.remove();box.querySelector('.commercial-close').onclick=close;box.onclick=e=>{if(e.target===box)close()};box.querySelector('form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget),lead={name:f.get('name'),email:f.get('email'),org:f.get('org'),role:f.get('role'),marketing:!!f.get('marketing'),date:new Date().toISOString()};state.lead=lead;save();if(isLead){mailOffer(en?'Full GDPR self-assessment request':'Demande d’auto-évaluation RGPD complète',['Bonjour Innocent','',en?'I would like to receive the full GDPR self-assessment.':'Je souhaite accéder à l’auto-évaluation RGPD complète.','',`Nom / Name : ${lead.name}`,`Organisation : ${lead.org}`,`Fonction / Role : ${lead.role}`,`E-mail : ${lead.email}`,`Référence : ${state.reportId}`]);state.mode='complet';state.started=true;save();close();render()}else{mailOffer(en?'Evidence-based GDPR audit request':'Demande d’audit RGPD fondé sur des preuves',['Bonjour Innocent','',`Nom / Name : ${lead.name}`,`Organisation : ${lead.org}`,`Fonction / Role : ${lead.role}`,`E-mail : ${lead.email}`,`Taille / Size : ${f.get('size')}`,`Échéance / Deadline : ${f.get('deadline')}`,`Contexte / Context : ${f.get('context')||'-'}`,`Référence : ${state.reportId}`]);box.querySelector('.form-note').textContent=en?'Send the opened email to confirm your request.':'Envoyez le message ouvert pour confirmer votre demande.'}}}
function injectCommercial(){const en=state.lang==='en',c=commercialCopy[en?'en':'fr'];if(!state.started){const grid=root.querySelector('.modeGrid'),start=root.querySelector('#start');if(!grid||!start)return;const cards=grid.querySelectorAll(':scope > button');if(cards[0])cards[0].insertAdjacentHTML('beforeend','<mark>'+c.express+'</mark>');if(cards[1])cards[1].insertAdjacentHTML('beforeend','<mark>'+c.complete+'</mark>');if(cards[2])cards[2].insertAdjacentHTML('beforeend','<mark>'+c.audit+'</mark>');start.textContent=c.start+' →';start.onclick=()=>{if(state.mode==='complet'&&!state.lead)return commercialModal('lead');if(state.mode==='audit'){if(!auditAccess())return commercialModal('audit');if(state.auditQuestionsLoaded){state.started=true;return render()}start.disabled=true;window.RGPD_API.getAuditQuestions().then(result=>{(result.questions||[]).forEach(q=>{if(q.en){EN_DATA[q.id]=[q.en.text,q.en.proof,q.en.action];delete q.en}if(q.reportStep){REPORT_STEPS[q.id]=q.reportStep;delete q.reportStep}q._fr={axis:q.axis,text:q.text,proof:q.proof,action:q.action};if(!Qs.some(e=>e.id===q.id))Qs.push(q)});state.auditQuestionsLoaded=true;start.disabled=false;state.started=true;render()}).catch(err=>{start.disabled=false;alert((state.lang==='en'?'Unable to load audit questions: ':'Impossible de charger les questions d\u2019audit : ')+err.message)});return}state.started=true;render()};const offers=document.createElement('section');offers.className='commercial-offers';offers.innerHTML='<small>DU DIAGNOSTIC À LA MISSION</small><h2>'+c.offers+'</h2><div><article><b>01</b><h3>'+(en?'Quick assessment':'Diagnostic express')+'</h3><p>'+(en?'10 essential checks, immediate score and priorities.':'10 contrôles essentiels, score immédiat et priorités.')+'</p><strong>0 €</strong></article><article><b>02</b><h3>'+(en?'Personalised analysis':'Analyse personnalisée')+'</h3><p>'+c.analysisSub+'</p><strong>290 € HT</strong><button data-buy="analysis">'+c.analysis+'</button></article><article><b>03</b><h3>'+(en?'Evidence-based audit':'Audit fondé sur des preuves')+'</h3><p>'+(en?'Interviews, document review, findings and remediation plan.':'Entretiens, revue documentaire, constats et plan de remédiation.')+'</p><strong>'+(en?'Quotation':'Sur devis')+'</strong><button data-buy="audit">'+c.auditCta+'</button></article><article><b>04</b><h3>'+(en?'White-label licence':'Licence marque blanche')+'</h3><p>'+(en?'Custom branding, questionnaire and recurring updates.':'Identité, questionnaire et mises à jour personnalisés.')+'</p><strong>'+(en?'From €490/year':'Dès 490 €/an')+'</strong><button data-buy="licence">'+c.licence+'</button></article></div><p class="payment-note">'+(en?'The €290 button is ready for your Stripe Payment Link. Until then, it sends a qualified email request.':'Le bouton à 290 € est prêt à recevoir votre lien Stripe. En attendant, il envoie une demande qualifiée par e-mail.')+'</p>';grid.parentNode.insertBefore(offers,root.querySelector('.support-bar'));offers.querySelector('[data-buy=analysis]').onclick=()=>mailOffer('Analyse personnalisée RGPD — 290 € HT',['Bonjour Innocent','','Je souhaite réserver une analyse personnalisée de mes résultats RGPD (290 € HT).',`Référence : ${state.reportId}`,'','Merci de m’indiquer les modalités de paiement et de rendez-vous.']);offers.querySelector('[data-buy=audit]').onclick=()=>commercialModal('audit');offers.querySelector('[data-buy=licence]').onclick=()=>mailOffer('Demande de licence — Matrice RGPD',['Bonjour Innocent','','Je souhaite étudier une version personnalisée / marque blanche de la matrice RGPD.','','Organisation :','Nombre d’utilisateurs ou de clients :','Personnalisation souhaitée :'])}else{const report=root.querySelector('.report');if(report){const action=document.createElement('div');action.className='result-offers';action.innerHTML='<small>PROCHAINE ÉTAPE · '+state.reportId+'</small><h2>'+c.analysis+'</h2><p>'+c.analysisSub+'</p><div><button data-result="analysis">'+c.analysis+' — 290 € HT</button><button data-result="audit">'+c.auditCta+'</button></div>';report.insertAdjacentElement('afterend',action);action.querySelector('[data-result=analysis]').onclick=()=>mailOffer('Analyse personnalisée RGPD — 290 € HT',['Bonjour Innocent','','Je souhaite faire analyser mes résultats.',`Référence : ${state.reportId}`,`Parcours : ${modes[state.mode][0]}`,`Score : ${calc(active())} %`,`Coordonnées : ${state.lead?state.lead.name+' — '+state.lead.org:'à compléter'}`]);action.querySelector('[data-result=audit]').onclick=()=>commercialModal('audit')}}}
