const analysisPricing={micro:{fr:'1 à 9 salariés',en:'1 to 9 employees',price:'290 € HT',companySize:'1-9',stripe:'https://buy.stripe.com/aFacN4dfp7A21pcfOCenS03'},small:{fr:'10 à 49 salariés',en:'10 to 49 employees',price:'490 € HT',companySize:'10-49',stripe:'https://buy.stripe.com/4gM4gy8Z92fI2tgdGuenS02'},medium:{fr:'50 à 249 salariés',en:'50 to 249 employees',price:'790 € HT',companySize:'50-249',stripe:'https://buy.stripe.com/eVq28q6R13jM5FsfOCenS04'},large:{fr:'250 salariés et plus',en:'250 employees or more',price:'Sur devis',companySize:'250+',stripe:null}};
function stripeCheckoutUrl(base,email,leadId,assessmentId,companySize){const u=new URL(base);if(email)u.searchParams.set('prefilled_email',email);const parts=['R='+String(state.reportId||'').replace(/\|/g,'-')];if(leadId)parts.push('L='+leadId);if(assessmentId)parts.push('A='+assessmentId);if(companySize)parts.push('S='+companySize);u.searchParams.set('client_reference_id',parts.join('|').slice(0,200));u.searchParams.set('locale',state.lang==='en'?'en':'fr');u.searchParams.set('utm_source','matrice_rgpd');u.searchParams.set('utm_medium','website');u.searchParams.set('utm_campaign','analyse_personnalisee');return u.toString()}
function analysisPricingModal(){const en=state.lang==='en',box=document.createElement('div');box.className='commercial-modal';const options=Object.entries(analysisPricing).map(([key,v])=>'<option value="'+key+'">'+(en?v.en:v.fr)+'</option>').join('');box.innerHTML='<form class="commercial-dialog pricing-dialog" data-stripe-checkout="1"><button type="button" class="commercial-close" aria-label="Fermer">×</button><small>ANALYSE PERSONNALISÉE</small><h2>'+(en?'A price matched to your organisation':'Un tarif adapté à votre organisation')+'</h2><p>'+(en?'Select your workforce. The stated price covers a review of your results, a one-hour discussion and a prioritised roadmap.':'Sélectionnez votre effectif. Le tarif comprend la revue des résultats, un échange d’une heure et une feuille de route priorisée.')+'</p><label class="size-picker">'+(en?'Organisation size':'Effectif de l’entreprise')+' *<select name="size">'+options+'</select></label><div class="calculated-price"><span>'+(en?'Your indicative price':'Votre tarif indicatif')+'</span><strong>290 € HT</strong></div><div class="lead-grid"><label>'+(en?'Full name':'Nom et prénom')+' *<input name="name" required autocomplete="name"></label><label>'+(en?'Professional email':'E-mail professionnel')+' *<input name="email" required type="email" autocomplete="email"></label><label class="wide">'+(en?'Organisation':'Organisation')+' *<input name="org" required autocomplete="organization"></label></div><label class="check"><input name="consent" type="checkbox" required> '+(en?'I agree to be contacted about this request.':'J’accepte d’être recontacté au sujet de cette demande.')+' <a href="confidentialite.html">'+(en?'Privacy policy':'Politique de confidentialité')+'</a></label><button class="commercial-submit">'+(en?'Pay securely with Stripe':'Payer en ligne avec Stripe')+' →</button><p class="scope-note">'+(en?'Secure payment is handled by Stripe. Billing details are collected during checkout. Organisations with 250+ employees are handled by quotation.':'Le paiement sécurisé est traité par Stripe. Les informations de facturation sont recueillies lors du paiement. À partir de 250 salariés, la prestation est proposée sur devis.')+'</p><p class="form-note"></p></form>';document.body.appendChild(box);const form=box.querySelector('form'),select=form.elements.size,price=box.querySelector('.calculated-price strong'),submit=form.querySelector('.commercial-submit'),note=form.querySelector('.form-note'),close=()=>box.remove();function refreshTier(){const tier=analysisPricing[select.value];price.textContent=tier.price;submit.textContent=tier.stripe?(en?'Pay '+tier.price+' with Stripe →':'Payer '+tier.price+' avec Stripe →'):(en?'Request a quotation →':'Demander un devis →')}select.onchange=refreshTier;refreshTier();box.querySelector('.commercial-close').onclick=close;box.onclick=e=>{if(e.target===box)close()};form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form),tier=analysisPricing[f.get('size')],name=String(f.get('name')||'').trim(),email=String(f.get('email')||'').trim(),org=String(f.get('org')||'').trim();state.lead={name,email,org,date:new Date().toISOString()};save();if(!tier.stripe){mailOffer(en?'Personalised GDPR analysis — quotation request':'Analyse personnalisée RGPD — demande de devis',['Bonjour Innocent','',en?'I would like a quotation for a personalised GDPR analysis.':'Je souhaite obtenir un devis pour une analyse personnalisée RGPD.',`Nom / Name : ${name}`,`Organisation : ${org}`,`E-mail : ${email}`,`Effectif / Workforce : ${en?tier.en:tier.fr}`,`Référence : ${state.reportId}`]);note.textContent=en?'Your email app will open with the quotation request.':'Votre messagerie va s’ouvrir avec la demande de devis.';return}submit.disabled=true;submit.textContent=en?'Preparing secure payment…':'Préparation du paiement sécurisé…';note.textContent='';let leadId=localStorage.getItem('rgpd-current-lead-id')||'';let assessmentId=localStorage.getItem('rgpd-current-assessment-id')||'';try{if(window.RGPD_API?.createLead){const leadResult=await window.RGPD_API.createLead({fullName:name,professionalEmail:email,organisation:org,roleTitle:'',companySize:tier.companySize,contactConsent:true,marketingConsent:false,source:'github-pages-v6.2-stripe-webhook'});if(leadResult?.leadId){leadId=leadResult.leadId;localStorage.setItem('rgpd-current-lead-id',leadId);const commercial={leadId,requestType:'analysis',companySize:tier.companySize,context:'Paiement Stripe — '+tier.price+' — '+state.reportId};if(assessmentId)commercial.assessmentId=assessmentId;try{await window.RGPD_API.createCommercialRequest(commercial)}catch(err){console.warn('Demande commerciale Supabase non enregistrée avant Stripe :',err)}}}}catch(err){console.warn('Prospect Supabase non enregistré avant Stripe :',err)}localStorage.setItem('rgpd-pending-stripe-tier',select.value);localStorage.setItem('rgpd-pending-stripe-reference',state.reportId);location.href=stripeCheckoutUrl(tier.stripe,email,leadId,assessmentId,tier.companySize)}}
function applySizePricing(){const en=state.lang==='en',offerButton=root.querySelector('[data-buy="analysis"]'),resultButton=root.querySelector('[data-result="analysis"]'),note=root.querySelector('.payment-note');if(offerButton){const card=offerButton.closest('article'),price=card&&card.querySelector('strong');if(price)price.textContent=en?'From €290 excl. tax':'Dès 290 € HT';offerButton.onclick=analysisPricingModal}if(resultButton){resultButton.textContent=en?'Personalised analysis — from €290 excl. tax':'Analyse personnalisée — dès 290 € HT';resultButton.onclick=analysisPricingModal}if(note)note.textContent=en?'Secure Stripe payment for organisations with 1–249 employees. 250+ employees: quotation.':'Paiement sécurisé Stripe pour les organisations de 1 à 249 salariés. À partir de 250 salariés : sur devis.'}
const v51Render=render;render=function(){v51Render();applySizePricing()};render();


/* V6 — séparation stricte client / auditeur, sans modification de l'identité visuelle. */
function applyV6AuditUI(){
  if(state.started)return;
  const en=state.lang==='en';
  const grid=root.querySelector('.modeGrid');
  const start=root.querySelector('#start');
  if(!grid||!start)return;
  const cards=grid.querySelectorAll(':scope > button');
  const auditCard=cards[2];
  if(auditCard){
    const mark=auditCard.querySelector('mark');
    if(mark){
      mark.textContent=auditAccess()
        ? (en?'AUDITOR ACCESS':'ACCÈS AUDITEUR')
        : (en?'Auditor-led · quotation':'Réalisé par un auditeur · sur devis');
    }
  }
  if(state.mode==='audit'){
    start.textContent=(auditAccess()
      ? (en?'Open professional audit':'Ouvrir l’audit professionnel')
      : (en?'Request an audit':'Demander un audit'))+' →';
  }
}

const v6Render=render;
render=function(){v6Render();applyV6AuditUI()};
document.addEventListener('rgpd-admin-auth-change',()=>{
  // Une session peut être restaurée quelques millisecondes après le premier rendu.
  // Le bouton Audit est alors actualisé automatiquement sans rechargement manuel.
  render();
});
render();
